import * as z from "zod/v4";
import { registerContinuation, registerContinuationChannel, } from "../../internal/continuation-registration.js";
import { createResourceChannel } from "../../internal/resource-channel.js";
import { MATCH_READY_EVENT_TYPE, } from "./types.js";
const matchReadyResourceSchema = z
    .object({
    name: z.string().min(1),
    planRevision: z.string(),
})
    .passthrough();
const matchReadyEventSchema = z.object({
    eventId: z.string().min(1),
    eventType: z.literal(MATCH_READY_EVENT_TYPE),
    teamId: z.string().min(1),
    occurredAtMs: z.number().int().nonnegative(),
    changeMonitor: matchReadyResourceSchema,
});
const pack = createResourceChannel({
    kind: "match_ready",
    eventTypes: [MATCH_READY_EVENT_TYPE],
    eventSchema: matchReadyEventSchema,
    replayDescription: "Replay a change_monitor.match_ready event.",
    invalidError: "invalid match_ready event",
});
export function matchReadyChannel(options) {
    return pack.channel(options);
}
export function getMatchReadyChannelOptions(definition) {
    return pack.getOptions(definition);
}
registerContinuationChannel({
    kind: "match_ready",
    getOptions: getMatchReadyChannelOptions,
    usesDeclaredEvents: true,
});
registerContinuation({
    type: "match-ready",
    kind: "match_ready",
    events: [MATCH_READY_EVENT_TYPE],
    format: "match_ready:{changeMonitorName}",
    selector: "match_ready.monitor/v2",
});
